		// 没有可用的 2D 摄像机时退化为直接缩放场景根节点，避免设计坐标被当成像素使用
		scene.scaleX = scale;
		scene.scaleY = scale;
		return;
	}
	camera.zoom = scale;
	scene.scaleX = 1;
	scene.scaleY = 1;
};

