	private enemyAct(): void {
		const damage = this.combat.enemyAct();
		const action = this.combat.lastEnemyAction;
		if (action === EnemyAction.Charge) {
			// 蓄力：本次不出手，仅预告下一次重击
			this.hud.showNotice('精英蓄力中 — 下次行动重击', NoticeLane.Enemy, 0xffb36b);
