		}
	},
	[EffectKind.DebuffArmor]: (context, spec) => {
		for (const target of resolveTargets(context, spec.target)) {
			target.debuffStacks += Math.round(spec.value);
		}
	},
	[EffectKind.ManaGain]: (context, spec) => {
		for (const target of resolveTargets(context, spec.target)) {
