/**
 * 全局配置表。所有可调数值集中在这里，便于手感快速调参。
 */
export class Config {
	/** 设计基准高度：摄像机 zoom 按该高度适配。 */
	static readonly DesignSceneHeight = 1080;
	/** 设计基准宽度：与高度一起取“缩放取最小”，保证 7×7 棋盘在任何宽高比下不被横向裁切。 */
