/** 单波敌人的纯数据定义。 */
export interface WaveDef {
	name: string;
	isElite: boolean;
	hp: number;
	attack: number;
	heavyAttack: number;
	armor: number;
	actionTurns: number;
	actionSeconds: number;
}

/**
 * 全局配置表。所有可调数值集中在这里，便于手感快速调参。
 */
export class Config {
