new:
```
	/**
	 * 敌人出手：先推进封锁计时，再按当前波的技能表轮转选择技能。
	 * - 技能带 `preparesNext` 时，本次行动只蓄力预告（返回 0），下一次行动才释放；
	 * - 技能效果（如重击封锁棋盘）经统一执行器下发，伤害由技能自带的 damage 缩放后结算；
	 * - 全部技能都在冷却时回退到波次普通攻击，保证敌人永远能出手。
	 */
	enemyAct(): number {
		// 先推进封锁计时：到期的封锁格自动恢复为常规方块（恢复走棋盘标准补充流程），
		// 因此本次刚下发的封锁不会被立刻扣减。
		this.expiredLockCount = this.board.expireLocks();
		const wave = this.currentWave();
		const scale = this.difficultyScale * Config.stageEnemyScale(this.stage);
		for (let i = 0; i < this.cooldowns.length; i++) {
			if (this.cooldowns[i] > 0) {
				this.cooldowns[i]--;
			}
		}
		this.newLockCount = 0;
		if (this.prepared >= 0) {
			const index = this.prepared;
			this.prepared = -1;
			if (index < wave.skills.length) {
				const skill = wave.skills[index];
				this.cooldowns[index] = skill.cooldownActions;
				return this.performSkill(skill, scale, EnemyAction.Release);
			}
		}
		const picked = this.pickSkill(wave);
		if (picked.skill.preparesNext) {
			this.prepared = picked.index;
			this.lastSkill = picked.skill.name;
			this.lastAction = EnemyAction.Prepare;
			return 0;
		}
		return this.performSkill(picked.skill, scale, EnemyAction.Attack);
	}

	/** 执行一次技能：下发效果三元组、统计新封锁格数并结算伤害，返回造成的生命伤害。 */
	private performSkill(skill: EnemySkillDef, scale: number, action: EnemyAction): number {
		this.lastSkill = skill.name;
		this.lastAction = action;
		const locksBefore = this.board.lockedCount();
		if (skill.effects.length > 0) {
			this.applySpecs(skill.effects);
		}
		this.newLockCount = this.board.lockedCount() - locksBefore;
		if (skill.damage <= 0) {
			return 0;
		}
		return applyDamage(this.player, skill.damage * scale);
	}

	/** 轮转选取当前波第一个未冷却的技能；全部冷却时回退到波次普通攻击（index = -1）。 */
	private pickSkill(wave: WaveDef): { skill: EnemySkillDef; index: number } {
		const count = wave.skills.length;
		for (let step = 0; step < count; step++) {
			const index = (this.skillCursor + step) % count;
			if (this.cooldowns[index] <= 0) {
				this.skillCursor = (index + 1) % count;
				return { skill: wave.skills[index], index };
			}
		}
		this.skillCursor = 0;
		return { skill: Levels.fallbackSkill(wave), index: -1 };
	}
