```
	/**
	 * 敌人出手：按当前波次的技能表轮转选择技能（数据驱动，无按技能/按精英的硬编码分支）——
	 * - 命中的技能若 `preparesNext` 为真，则本次只蓄力预告（0 伤害、不下发效果），下次行动释放它；
	 * - 释放/普通攻击时，技能效果交统一执行器（封锁棋盘走 BoardBlock），
	 *   伤害由技能自带 damage 乘「难度 × 关卡」缩放后结算。
	 */
	enemyAct(): number {
		// 先推进封锁计时：到期的封锁格自动恢复为常规方块（恢复走棋盘标准补充流程），
		// 因此本次刚下发的封锁不会被立刻扣减。
		this.expiredLockCount = this.board.expireLocks();
		this.lastNewLocks = 0;
		const wave = this.currentWave();
		// 推进技能冷却（释放时写入的冷却不会被本次同回合扣减）
		for (let i = 0; i < this.cooldowns.length; i++) {
			if (this.cooldowns[i] > 0) {
				this.cooldowns[i]--;
			}
		}
		if (this.prepared >= 0) {
			const index = this.prepared;
			const skill = this.pickSkillAt(wave, index);
			this.prepared = -1;
			this.cooldowns[index] = skill.cooldownActions;
			this.lastSkill = skill.name;
			this.lastAction = EnemyAction.Release;
			return this.strike(skill);
		}
		const index = this.pickSkillIndex(wave);
		const skill = this.pickSkillAt(wave, index);
		this.skillCursor = index + 1;
		this.lastSkill = skill.name;
		if (skill.preparesNext) {
			this.prepared = index;
			this.lastAction = EnemyAction.Prepare;
			return 0;
		}
		this.lastAction = EnemyAction.Attack;
		return this.strike(skill);
	}
