Wait `pickSkillIndex` and `pickSkillAt`: pickSkillIndex rotates from cursor, returns index of skill with cooldown<=0; if none, returns -1 meaning fallback. pickSkillAt(wave, index) returns wave.skills[index] or Levels.fallbackSkill(wave) when index<0.

```
	/** 从轮转起点挑一个冷却为 0 的技能下标；全部冷却中时返回 -1（改用兜底普攻）。 */
	private pickSkillIndex(wave: WaveDef): number {
		const count = wave.skills.length;
		if (count <= 0) {
			return -1;
		}
		for (let i = 0; i < count; i++) {
			const index = (this.skillCursor + i) % count;
			if (this.cooldowns[index] <= 0) {
				return index;
			}
		}
		return -1;
	}

	/** 按下标取技能；下标为 -1（全冷却）时用波次自身攻击力构造的兜底普攻。 */
	private pickSkillAt(wave: WaveDef, index: number): EnemySkillDef {
		if (index < 0 || index >= wave.skills.length) {
			return Levels.fallbackSkill(wave);
		}
		return wave.skills[index];
	}

	/** 释放一个技能：效果交统一执行器，伤害按难度与关卡缩放后结算给玩家。 */
	private strike(skill: EnemySkillDef): number {
		const lockedBefore = this.board.lockedCount();
		this.applySpecs(skill.effects);
		this.lastNewLocks = this.board.lockedCount() - lockedBefore;
		const scale = this.difficultyScale * Config.stageEnemyScale(this.stage);
		return applyDamage(this.player, skill.damage * scale);
	}
