new:
```
	enemyAct(): number {
		// 先推进封锁计时：到期的封锁格自动恢复为常规方块（恢复走棋盘标准补充流程），
		// 因此本次刚下发的封锁不会被立刻扣减。
		this.expiredLockCount = this.board.expireLocks();
		// 推进所有技能冷却（已归零的保持 0）
		for (let i = 0; i < this.cooldowns.length; i++) {
			if (this.cooldowns[i] > 0) {
				this.cooldowns[i] = this.cooldowns[i] - 1;
			}
		}
		const wave = this.currentWave();
		const scale = this.difficultyScale * Config.stageEnemyScale(this.stage);
		const lockedBefore = this.board.lockedCount();
		let skill: EnemySkillDef;
		if (this.prepared >= 0) {
			// 释放已预告的技能：写入冷却并清除预告（数值与效果仍走同一条数据）
			const releaseIndex = this.prepared;
			skill = this.skillAt(wave, releaseIndex);
			if (releaseIndex < this.cooldowns.length) {
				this.cooldowns[releaseIndex] = skill.cooldownActions;
			}
			this.prepared = -1;
			this.lastAction = EnemyAction.Release;
		} else {
			const picked = this.pickSkill(wave);
			skill = this.skillAt(wave, picked);
			if (picked >= 0 && skill.preparesNext) {
				// 蓄力预告：本次不出手、不结算效果与伤害
				this.prepared = picked;
				this.lastSkill = skill.name;
				this.blockedCells = 0;
				this.lastAction = EnemyAction.Prepare;
				return 0;
			}
			this.lastAction = EnemyAction.Attack;
		}
		this.lastSkill = skill.name;
		this.applySpecs(skill.effects);
		this.blockedCells = this.board.lockedCount() - lockedBefore;
		return applyDamage(this.player, skill.damage * scale);
	}

	/** 从轮转起点取第一个冷却结束的技能下标；全部冷却时返回 -1（退回普通攻击）。 */
	private pickSkill(wave: WaveDef): number {
		const count = wave.skills.length;
		for (let step = 0; step < count; step++) {
			const index = (this.skillCursor + step) % count;
			if (this.cooldowns[index] <= 0) {
				this.skillCursor = (index + 1) % count;
				return index;
			}
		}
		return -1;
	}

	/** 取指定下标技能；越界时退回由波次攻击力推导的普通攻击。 */
	private skillAt(wave: WaveDef, index: number): EnemySkillDef {
		if (index < 0 || index >= wave.skills.length) {
			return Levels.fallbackSkill(wave);
		}
		return wave.skills[index];
	}
