		if (!this.settings.saved) {
			this.hud.showNotice('设置未保存（仅内存态生效）');
		}
		this.root.schedule((dt) => {
			this.tick(dt);
			return false;
		});
	}

	/** 单帧逻辑：输入结算 → 实时倒计时 → HUD 刷新。 */
	private tick(dt: number): void {
