		} else {
			this.hud.showNotice('第 ' + this.combat.waveNumber + ' 波来袭');
		}
		// 换波时清除上一波（精英重击）留下的封锁格
		this.board.reset();
		this.view.refreshFromBoard();
		this.turnsUntilEnemy = this.combat.enemyInterval;
	}

