	}

	/** 可放置方块数量（生成/补充/连通统计只用前 placeableCount 条）。 */
	static placeableCount(): number {
		let count = 0;
		for (const def of BlockDefs.List) {
			if (def.placeable) {
				count++;
			}
		}
		return count;
