	expect(workBoard.deadlockWarningCount === 0, '消除补充后出现无解棋盘：' + workBoard.deadlockWarningCount + ' 次');
	expect(workBoard.clearedTotal === removedSum, '消除统计应与实际移除数一致：' + workBoard.clearedTotal + ' vs ' + removedSum);
