import { EffectKind, EffectRule, EffectTarget, makeRule } from 'game/Effects';

/** 一种方块的数据定义（无行为函数，全部为可读数据）。 */
export interface BlockDef {
	id: string;
	/** 外观色（0xRRGGBB）。 */
