};

/** 把效果列表格式化为可读文本：[物理伤害 13 → 当前敌人] */
export function formatEffects(specs: EffectSpec[]): string {
	const parts: string[] = [];
	for (const spec of specs) {
		parts.push(EffectKindNames[spec.kind] + ' ' + spec.value + ' → ' + EffectTargetNames[spec.target]);
	}
	return parts.join(' / ');
}

