/** 按 target 取接收者；未注册或预留的目标返回空列表。 */
export function resolveTargets(context: EffectContext, target: EffectTarget): ActorState[] {
	const resolver = targetResolvers[target];
	if (resolver === undefined) {
		return [];
	}
	return resolver(context);
}

