	expect(damageValue === 10, '链长 2 物理伤害应为 4+3×2=10，实际 ' + damageValue);
	expect(manaValue === 7, '链长 2 魔力应为 1+3×2=7，实际 ' + manaValue);

	const manaCombat = new Combat(new Board());
