	expect(manaCombat.enemy.hp === 34, '物理伤害 10 受护甲 4 减免后敌人应为 34 HP，实际 ' + manaCombat.enemy.hp);
	manaCombat.player.mana = 0;
	for (let i = 0; i < 30; i++) {
