	expect(ChainTiers.multiplierOf(2) === 1, '接触档倍率应为 1.0，实际 ' + ChainTiers.multiplierOf(2));
	const specValue = (specs: EffectSpec[], kind: EffectKind, target: EffectTarget): number => {
