	expect(comboDamage > contactDamage && resonanceDamage > comboDamage && overloadDamage > resonanceDamage, '高链长档位的数值应严格更大：' + contactDamage + '/' + comboDamage + '/' + resonanceDamage + '/' + overloadDamage);
	// 魔力规则显式 scaled=false，不受档位倍率影响：恒为 1 + 3n。
