	expect(specValue(overloadSpecs, EffectKind.PhysicalDamage, EffectTarget.AllEnemies) > 0, '超载档应解锁全体溅射');
	expect(specValue(resolveEffects(healRules, 3), EffectKind.Dispel, EffectTarget.Self) === 0, '链长 3 不应解锁净化');
