	BoardBlast = 'boardBlast',
}

/** 效果作用对象。`Reserved` 为预留未实现的枚举位。 */
export const enum EffectTarget {
	Self = 'self',
	CurrentEnemy = 'currentEnemy',
	AllEnemies = 'allEnemies',
	Board = 'board',
	Reserved = 'reserved',
}

/** 严格三元组：执行效果 / 执行数值 / 执行对象。不带可选字段，A避免 Lua 数组存 undefined。 */
export interface EffectSpec {
	kind: EffectKind;
	value: number;
	target: EffectTarget;
}

/** 纯数据规则：“链长 → 数值”也是数据，不是函数。 */
export interface EffectRule {
	kind: EffectKind;
	target: EffectTarget;
	/** 链长下限时的数值。 */
	base: number;
	/** 每多一块的增量（可为 0）。 */
	perBlock: number;
	/** 生效所需最小链长。 */
	minChain: number;
	/** 取整粒度：0 = 四舍五入；>0 = 向下取整到该粒度。 */
	floorTo: number;
	/** 是否受链长档位数值倍率（game/ChainTiers.ts）影响；false 表示按原值产出（如魔力）。 */
	scaled: boolean;
}

/** 构造一条效果规则，避免各处重复写全字段。 */
export function makeRule(kind: EffectKind, target: EffectTarget, base: number, perBlock: number, minChain: number = Config.MinChainLength, floorTo: number = 0, scaled: boolean = true): EffectRule {
	return { kind, target, base, perBlock, minChain, floorTo, scaled };
}

/** 按取整粒度把原始数值归整。 */
export function roundRuleValue(raw: number, floorTo: number): number {
	if (floorTo > 0) {
		return Math.floor(raw / floorTo) * floorTo;
	}
	return Math.round(raw);
}

/**
 * 把方块的效果规则展开为效果三元组列表。
 * 链长低于规则下限时跳过该条；链长低于全局下限时统一返回空列表。
 */
export function resolveEffects(rules: EffectRule[], chainLength: number): EffectSpec[] {
	const specs: EffectSpec[] = [];
	if (chainLength < Config.MinChainLength) {
		return specs;
	}
	// 分阶段强化：先取链长所在档位的数值倍率，再逐条按“是否受倍率影响”展开数值。
	const tierMultiplier = ChainTiers.multiplierOf(chainLength);
	for (const rule of rules) {
		if (chainLength < rule.minChain) {
			continue;
		}
		let raw = rule.base + rule.perBlock * chainLength;
		if (rule.scaled) {
			raw *= tierMultiplier;
		}
		specs.push({ kind: rule.kind, value: roundRuleValue(raw, rule.floorTo), target: rule.target });
	}
	return specs;
}

