/** 执行效果的种类。新增效果种类 = 注册一条 handler（本直文件只列枚举）。 */
export const enum EffectKind {
	PhysicalDamage = 'physicalDamage',
	MagicDamage = 'magicDamage',
	Heal = 'heal',
	Dispel = 'dispel',
	Shield = 'shield',
	BuffDamage = 'buffDamage',
