	static indexOf(id: string): number {
		const list = BlockDefs.List;
		for (let i = 0; i < list.length; i++) {
			if (list[i].id === id) {
				return i;
			}
		}
		return -1;
	}

	static find(id: string): BlockDef | undefined {
		const index = BlockDefs.indexOf(id);
