	/** 系统提示（波次/关卡/设置/技能）飘字分道：与上两条互不重叠。 */
	static readonly NoticeSystemX = 0;
	static readonly NoticeSystemY = -120;
	/** 受击反馈：血条闪白/闪红持续秒数与全屏受击红闪峰值透明度。 */
