	static readonly List: BlockDef[] = [
		{
			id: BlockDefs.Physical,
			color: 0xe2574c,
			glyph: '物',
			placeable: true,
			rules: [
				makeRule(EffectKind.PhysicalDamage, EffectTarget.CurrentEnemy, 4, 3),
