	get enemyInterval(): number {
		return this.currentWave().actionTurns;
	}

	/** 是否实时模式（敌人按秒倒计时行动）。 */
	get isRealtime(): boolean {
		return this.realtime;
	}

	/** 当前波次的敌人行动间隔（实时模式：秒）。 */
	get enemyIntervalSeconds(): number {
		return this.currentWave().actionSeconds;
	}

