	}

	/** 最近一次敌人行动使用/预告的技能名。 */
	get lastSkillName(): string {
		return this.lastSkill;
	}

	/** 最近一次敌人行动经执行器新封锁的棋盘格数。 */
	get lastNewLocks(): number {
		return this.newLocks;
	}

	/** 最近一次敌人行动的类别（在 enemyAct() 之后读取）。 */
	get lastEnemyAction(): EnemyAction {
