/** 把 0xRRGGBB 转成 Dora 的 Color 对象。 */
export function colorFromHex(hex: number, alpha: number = 255): Color.Type {
	const r = Math.floor(hex / 65536) % 256;
	const g = Math.floor(hex / 256) % 256;
	const b = hex % 256;
