		// 因此本次刚下发的封锁不会被立刻扣减。
		this.expiredLockCount = this.board.expireLocks();
		// 推进技能冷却（本次释放的技能会在其分支里被重新设为满冷却）。
		for (let i = 0; i < this.cooldowns.length; i++) {
