	onCycleDifficulty: () => void = () => {};
	onToggleHint: () => void = () => {};

	constructor(skills: SkillDef[]) {
		const root = Node();
		this.root = root;

		// 全屏受击红闪：z 低于 HUD 其它元素（不遮挡文字与面板），也不拦截触控
		const hitLayer = DrawNode();
		hitLayer.z = -1;
