	}

	get isSettingsOpen(): boolean {
		return this.settingsOpen;
	}

	toggleSettings(): void {
		if (this.settingsOpen) {
			this.closeSettings();
			return;
		}
		this.openSettings();
	}

	openSettings(): void {
		this.settingsOpen = true;
		for (const part of this.settingsPanelParts) {
			part.visible = true;
		}
		for (const button of this.settingsButtons) {
			button.setEnabled(true);
		}
