/** 封锁棋盘的效果条目（走统一执行器的棋盘效果，等级数据只给格数与时机）。 */
function blockSpec(cells: number): EffectSpec {
	return { kind: EffectKind.BoardBlock, value: cells, target: EffectTarget.Board };
