		}
		return '棋盘无可连线区域，已重排棋盘（生命 −' + Config.BoardResetPenalty + '）';
	}

	private makeContext(): EffectContext {
		return { player: this.player, currentEnemy: this.enemy, allEnemies: this.enemies, board: this.board };
	}
