function collectOption(board: Board, options: number[], used: boolean[], col: number, row: number, type: number): void {
	if (!board.inside(col, row)) {
		return;
	}
	const flat = board.flatIndex(col, row);
	if (used[flat] || board.cellIndex(col, row) !== type) {
