	/** 对比快照，返回方块类型发生变化的格子下标（flat）；无变化时返回空列表。 */
	private diffBlocks(before: number[]): number[] {
		const changed: number[] = [];
		let i = 0;
		for (let row = 0; row < this.board.rows; row++) {
