	/** 可释放的技能列表，供 HUD 绘制按钮。 */
	availableSkills(): SkillDef[] {
		return Skills.List;
	}

	/**
	 * 棋盘可执行性兜底：不可执行（所有颜色都不存在 ≥ MinChainLength 的区域）时
	 * 直接重排整盘并惩罚玩家，返回提示文本；返回 undefined 表示无需处理。
	 */
	ensureBoardPlayable(): string | undefined {
		if (this.board.isPlayable()) {
			return undefined;
		}
